import{_ as e,o,c as r,a4 as a}from"./chunks/framework.bruR1JhL.js";const s="/tilepress/screenshots/photo-editor.webp",u=JSON.parse('{"title":"Edit & brand","description":"Adjust and decorate a photo in the Photo editor, and stamp text or a logo on many images at once.","frontmatter":{"title":"Edit & brand","description":"Adjust and decorate a photo in the Photo editor, and stamp text or a logo on many images at once."},"headers":[],"relativePath":"docs/img-edit.md","filePath":"docs/img-edit.md","lastUpdated":1795509372000}'),n={name:"docs/img-edit.md"};function d(i,t,l,h,g,c){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="edit-brand" tabindex="-1">Edit &amp; brand <a class="header-anchor" href="#edit-brand" aria-label="Permalink to &quot;Edit &amp; brand&quot;">​</a></h1><p>These tools are under the <strong>Edit &amp; Brand</strong> tab in the <strong>Images</strong> section. The Photo editor works on one picture at a time: light and colour, looks, rotation, and layers of text, drawings, shapes and logos. Watermark Image stamps text or a logo on a whole batch of images.</p><p>Both tools save new files and never change the originals. The Photo editor&#39;s adjustments and the watermark preview are drawn by the same code that saves, so they show what you&#39;ll get. To open a picture in the Photo editor, right-click it in the Explorer and choose <strong>Edit photo</strong>, or click <strong>Edit photo</strong> in the Preview panel. See <a href="/tilepress/docs/interface">The Tilepress window</a> for the Explorer and the other general controls.</p><h2 id="photo-editor" tabindex="-1">Photo editor <a class="header-anchor" href="#photo-editor" aria-label="Permalink to &quot;Photo editor&quot;">​</a></h2><p>The Photo editor adjusts light and colour, applies a look, rotates or flips the picture, and adds text, freehand drawing, arrows, lines, boxes, ellipses and logos. Every change can be undone.</p><p><img src="'+s+'" alt="The Photo editor with a photo open and the Looks panel"></p><h3 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open an image: drag it from the Explorer onto the tool, click <strong>Open image…</strong>, or select it in the Explorer and click the <strong>Use</strong> button with its name.</li><li>Use the three panels on the right: <strong>Adjust</strong> for looks and sliders, <strong>Layers</strong> for text, drawings, shapes and logos, and <strong>Export</strong> for the file format.</li><li>Use the toolbar above the picture to add layers, rotate or flip, and undo or redo.</li><li>Click <strong>Save a copy…</strong> and choose where to save.</li></ol><p>After saving, the <strong>Saved</strong> card offers <strong>Open</strong>, <strong>Show in folder</strong> and <strong>Keep editing this file</strong>, which opens the saved copy in the editor.</p><h3 id="looks" tabindex="-1">Looks <a class="header-anchor" href="#looks" aria-label="Permalink to &quot;Looks&quot;">​</a></h3><p>The <strong>Look</strong> row on the <strong>Adjust</strong> panel shows <strong>Original</strong> and nine looks, each as a small preview of your photo. A look is a ready-made mix of the adjustments below. Anything you set with the sliders is added on top of it.</p><details class="details custom-block"><summary>What each look does</summary><table tabindex="0"><thead><tr><th>Look</th><th>Adjustments</th></tr></thead><tbody><tr><td><strong>Vivid</strong></td><td>Saturation +30, Contrast +12</td></tr><tr><td><strong>Warm</strong></td><td>Warmth +35, Saturation +8</td></tr><tr><td><strong>Cool</strong></td><td>Warmth −35</td></tr><tr><td><strong>Mono</strong></td><td>Saturation −100 (black and white)</td></tr><tr><td><strong>Noir</strong></td><td>Saturation −100, Contrast +40, Vignette +30</td></tr><tr><td><strong>Sepia</strong></td><td>A full sepia tone</td></tr><tr><td><strong>Vintage</strong></td><td>A partial sepia tone, Fade +30, Vignette +30, Contrast −8</td></tr><tr><td><strong>Fade</strong></td><td>Fade +45, Saturation −15</td></tr><tr><td><strong>Dramatic</strong></td><td>Contrast +35, Saturation −15, Vignette +35, Shadows −15</td></tr></tbody></table></details><h3 id="adjustments" tabindex="-1">Adjustments <a class="header-anchor" href="#adjustments" aria-label="Permalink to &quot;Adjustments&quot;">​</a></h3><p>The sliders are under <strong>Light &amp; colour</strong> on the <strong>Adjust</strong> panel. They all start at 0. Double-click a slider to set it back to 0. <strong>Reset adjustments</strong> goes back to <strong>Original</strong> with every slider at 0.</p><table tabindex="0"><thead><tr><th>Slider</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Exposure</strong></td><td>−100 to +100</td><td>Brightens or darkens the whole picture. +100 doubles the light, −100 halves it.</td></tr><tr><td><strong>Brightness</strong></td><td>−100 to +100</td><td>Lifts or lowers the mid-tones, leaving black and white as they are.</td></tr><tr><td><strong>Contrast</strong></td><td>−100 to +100</td><td>More or less difference between light and dark.</td></tr><tr><td><strong>Highlights</strong></td><td>−100 to +100</td><td>Brightens or darkens the bright areas.</td></tr><tr><td><strong>Shadows</strong></td><td>−100 to +100</td><td>Brightens or darkens the dark areas.</td></tr><tr><td><strong>Saturation</strong></td><td>−100 to +100</td><td>Stronger or weaker colours. −100 is black and white.</td></tr><tr><td><strong>Warmth</strong></td><td>−100 to +100</td><td>Warmer (more orange) or cooler (more blue).</td></tr><tr><td><strong>Tint</strong></td><td>−100 to +100</td><td>Positive values remove green (towards magenta), negative values add green.</td></tr><tr><td><strong>Hue</strong></td><td>−180 to +180</td><td>Shifts every colour around the colour wheel, in degrees.</td></tr><tr><td><strong>Sharpness / blur</strong></td><td>−100 to +100</td><td>Positive values sharpen, negative values blur.</td></tr><tr><td><strong>Vignette</strong></td><td>−100 to +100</td><td>Positive values darken the corners, negative values lighten them.</td></tr><tr><td><strong>Fade</strong></td><td>0 to 100</td><td>Lifts the blacks for a washed-out look.</td></tr></tbody></table><h3 id="rotate-and-flip" tabindex="-1">Rotate and flip <a class="header-anchor" href="#rotate-and-flip" aria-label="Permalink to &quot;Rotate and flip&quot;">​</a></h3><p>The toolbar has <strong>Rotate left</strong>, <strong>Rotate right</strong>, <strong>Flip horizontally</strong> and <strong>Flip vertically</strong>. Layers move with the picture: text and logos stay upright, while shapes, lines and drawings turn with it.</p><h3 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers&quot;">​</a></h3><p>Pick a tool in the toolbar, then click or drag on the photo. The toolbar shows a hint for the current tool on the right.</p><table tabindex="0"><thead><tr><th>Tool</th><th>How it works</th></tr></thead><tbody><tr><td><strong>Select</strong></td><td>Select, move and resize layers. Drag a selected layer to move it, or drag its handles to resize it.</td></tr><tr><td><strong>Text</strong></td><td>Click to add text. It starts as &quot;Your text&quot; in white bold Arial with a thin black outline. Change the words in the <strong>Layers</strong> panel.</td></tr><tr><td><strong>Draw</strong></td><td>Draw freehand.</td></tr><tr><td><strong>Arrow</strong></td><td>Drag from the tail to the tip.</td></tr><tr><td><strong>Line</strong></td><td>Drag to draw a straight line.</td></tr><tr><td><strong>Box</strong></td><td>Drag to draw a rectangle. A single click adds one at a default size.</td></tr><tr><td><strong>Ellipse</strong></td><td>Drag to draw an ellipse. A single click adds one at a default size.</td></tr><tr><td><strong>Logo / image</strong></td><td>Choose a picture file. It&#39;s placed in the bottom-right corner at a quarter of the photo&#39;s width.</td></tr></tbody></table><p>After you add a layer, the tool goes back to <strong>Select</strong> and the <strong>Layers</strong> panel opens with the new layer selected. The panel lists <strong>All layers (top first)</strong>; click one to select it.</p><p>While <strong>Draw</strong>, <strong>Arrow</strong>, <strong>Line</strong>, <strong>Box</strong> or <strong>Ellipse</strong> is chosen, the <strong>Layers</strong> panel shows the <strong>Pen</strong>: a row of colours (white, black, red, orange, yellow, green, blue and purple) plus a colour picker, and a <strong>Thickness</strong> slider from 1 to 40 (8 by default). New drawings, arrows and lines use both. New boxes and ellipses take the pen colour for their outline. The default pen colour is red.</p><p>The selected layer&#39;s settings appear in the <strong>Layers</strong> panel:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Settings</th></tr></thead><tbody><tr><td>Text</td><td>The text itself (several lines are fine). <strong>Font</strong>: Arial, Times New Roman, Courier New, Impact, Segoe Script or Comic Sans. <strong>Size (px)</strong>, <strong>Colour</strong>, <strong>Outline (px)</strong>, <strong>Outline colour</strong> (when there&#39;s an outline), <strong>Bold</strong>, <strong>Italic</strong> and <strong>Shadow</strong>.</td></tr><tr><td>Box and ellipse</td><td><strong>Outline</strong> with its colour and <strong>Width (px)</strong>, <strong>Fill</strong> with its colour, and <strong>Rounded corners</strong> (boxes only).</td></tr><tr><td>Drawing, line and arrow</td><td><strong>Colour</strong> and <strong>Thickness (px)</strong>.</td></tr><tr><td>Every layer</td><td><strong>Opacity</strong> (5 to 100%), <strong>Bring forward</strong>, <strong>Send back</strong> and <strong>Delete</strong>.</td></tr></tbody></table><p>To make text bigger or smaller, change <strong>Size (px)</strong>. Resizing a text layer&#39;s box doesn&#39;t scale the text.</p><h3 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h3><p>The <strong>Export</strong> panel has the <strong>Format</strong>: Same as the original (the default), JPG, PNG, WebP or AVIF. For JPG, WebP and AVIF, there&#39;s also <strong>Quality</strong>, from 10 to 100 (92 by default). It also shows the size the saved picture will have, in pixels.</p><h3 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Keys</th><th>Action</th></tr></thead><tbody><tr><td><kbd>Ctrl</kbd>+<kbd>Z</kbd></td><td>Undo</td></tr><tr><td><kbd>Ctrl</kbd>+<kbd>Y</kbd> or <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>Z</kbd></td><td>Redo</td></tr><tr><td><kbd>Delete</kbd> or <kbd>Backspace</kbd></td><td>Delete the selected layer</td></tr></tbody></table><p>The shortcuts don&#39;t apply while you&#39;re typing in a field. The toolbar also has undo and redo buttons. Up to 100 changes can be undone.</p><h3 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li><strong>Inputs:</strong> JPG, PNG, WebP, HEIC/HEIF, AVIF, GIF, BMP, TIFF and ICO. With <strong>Same as the original</strong>, HEIC photos are saved as JPG and ICO files as PNG.</li><li><strong>File name:</strong> the suggested name is the original name plus <code>_edited</code>, next to the original, for example <code>beach_edited.jpg</code>. If that file exists, a number is added, as in <code>beach_edited (2).jpg</code>.</li><li>The saved copy is full size. It keeps the photo&#39;s metadata (camera, date, location) and colour profile.</li><li>If you save a picture with transparent areas as JPG, those areas become white.</li><li>While you work, the adjustments are previewed on a smaller copy, and the layers are drawn on screen. When you save, everything is drawn again at full resolution, using the same Windows fonts.</li><li>Logos and other image layers can be any picture the image tools read. A PNG logo keeps its transparency.</li><li>Your edits stay while you switch to other tools. The Photo editor shares the open picture with Crop Image, Upscale Image, Remove background and Blur face, so opening a different picture in any of them (or using <strong>Keep editing this file</strong>) starts the editor afresh.</li></ul><h2 id="watermark-image" tabindex="-1">Watermark Image <a class="header-anchor" href="#watermark-image" aria-label="Permalink to &quot;Watermark Image&quot;">​</a></h2><p>Watermark Image stamps text or a logo on a batch of images, for example to mark photos as yours before you post them. The preview shows the real result on the selected image.</p><h3 id="how-to-use-it-1" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-1" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Add images: click <strong>Add images…</strong>, or drag an image from the Explorer onto the list.</li><li>Choose <strong>Text</strong> or <strong>Logo</strong>. <ul><li>For text, type it in the box. It starts as &quot;© Your name&quot;.</li><li>For a logo, click <strong>Choose a logo…</strong> and pick a picture.</li></ul></li><li>Set the size, opacity, rotation and position. Click an image in the list to preview the watermark on it.</li><li>Choose where to save: <strong>Save next to each image</strong>, or <strong>Save in a folder</strong> and click <strong>Choose…</strong>.</li><li>Click <strong>Watermark</strong> (with several images, the button says, for example, <strong>Watermark 5 images</strong>).</li></ol><p>To take an image off the list, click its ×. <strong>Clear list</strong> removes them all.</p><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Text</strong> / <strong>Logo</strong></td><td>What to stamp.</td><td>Text</td></tr><tr><td><strong>Font</strong></td><td>Text: Arial, Times New Roman, Impact, Segoe Script or Courier New.</td><td>Arial</td></tr><tr><td><strong>Colour</strong></td><td>Text colour.</td><td>White</td></tr><tr><td><strong>Bold</strong></td><td>Bold text.</td><td>On</td></tr><tr><td><strong>Dark outline</strong></td><td>A thin black outline around the text, so it shows on light backgrounds too.</td><td>On</td></tr><tr><td><strong>Size</strong> (text)</td><td>2 to 30% of the image&#39;s shorter side.</td><td>6%</td></tr><tr><td><strong>Size</strong> (logo)</td><td>3 to 90% of the image&#39;s width. The logo keeps its proportions.</td><td>22%</td></tr><tr><td><strong>Opacity</strong></td><td>5 to 100%.</td><td>60%</td></tr><tr><td><strong>Rotation</strong></td><td>−90° to 90°, in 5° steps. Positive values turn it anticlockwise.</td><td>0°</td></tr><tr><td><strong>Position</strong></td><td>One of 9 places: the corners, the middle of each edge, or the centre.</td><td>Bottom right</td></tr><tr><td><strong>Repeat across the image</strong></td><td>Tiles the watermark over the whole image, with every other row shifted by half a step.</td><td>Off</td></tr><tr><td><strong>Margin</strong></td><td>0 to 20% of the image&#39;s shorter side, between the watermark and the edge. Not used when repeating.</td><td>3%</td></tr><tr><td><strong>Spacing</strong></td><td>When repeating: the gap between copies, as a percentage of the watermark&#39;s size, from 10 to 300%.</td><td>80%</td></tr><tr><td><strong>Format</strong></td><td>Same as the original, JPG, PNG, WebP or AVIF.</td><td>Same as the original</td></tr></tbody></table><h3 id="good-to-know-1" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-1" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li><strong>Inputs:</strong> JPG, PNG, WebP, HEIC/HEIF, AVIF, GIF, BMP, TIFF and ICO, for both the images and the logo. With <strong>Same as the original</strong>, HEIC photos are saved as JPG and ICO files as PNG.</li><li><strong>File names:</strong> each copy gets the original name plus <code>_watermarked</code>, for example <code>IMG_0042_watermarked.jpg</code>. If that file exists, a number is added, as in <code>IMG_0042_watermarked (2).jpg</code>.</li><li>Because the size is relative to each image, the watermark looks the same on large and small pictures.</li><li>The text is a single line.</li><li>The quality for JPG, WebP and AVIF is fixed at 92.</li><li>The copies keep each photo&#39;s metadata and colour profile.</li><li>If one image can&#39;t be processed, the batch stops there and shows the error. The copies already saved stay.</li><li>The result appears in the <strong>Saved</strong> card with <strong>Open</strong> and <strong>Show in folder</strong> for each file.</li></ul>',41)])])}const m=e(n,[["render",d]]);export{u as __pageData,m as default};
